BEGIN;

-- Table: system_settings
CREATE TABLE system_settings (
	key VARCHAR(100) NOT NULL, 
	value TEXT, 
	description VARCHAR(255), 
	updated_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (key)
);

-- Table: users
CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255), 
	first_name VARCHAR(100) NOT NULL, 
	middle_name VARCHAR(100), 
	last_name VARCHAR(100) NOT NULL, 
	age INTEGER, 
	gender VARCHAR(20), 
	role VARCHAR(50) NOT NULL, 
	is_verified BOOLEAN, 
	email_verification_token VARCHAR(128), 
	reset_password_token VARCHAR(128), 
	reset_token_expiry TIMESTAMP WITHOUT TIME ZONE, 
	google_id VARCHAR(100), 
	is_active BOOLEAN, 
	house_no VARCHAR(100), 
	building VARCHAR(150), 
	street VARCHAR(150), 
	area VARCHAR(150), 
	city VARCHAR(100), 
	state VARCHAR(100), 
	country VARCHAR(100), 
	pincode VARCHAR(20), 
	phone VARCHAR(20), 
	gstin VARCHAR(30), 
	organization_name VARCHAR(200), 
	billing_address TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (google_id)
);

-- Table: courses
CREATE TABLE courses (
	id SERIAL NOT NULL, 
	slug VARCHAR(100) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	short_description TEXT NOT NULL, 
	overview TEXT, 
	estimated_duration VARCHAR(50), 
	language VARCHAR(50), 
	price_inr FLOAT, 
	gst_rate FLOAT, 
	price_usd FLOAT, 
	version VARCHAR(20), 
	is_active BOOLEAN, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: slides
CREATE TABLE slides (
	id SERIAL NOT NULL, 
	course_id INTEGER NOT NULL, 
	slide_number INTEGER NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	content_html TEXT NOT NULL, 
	image_url VARCHAR(500), 
	minimum_dwell_seconds INTEGER, 
	has_practice_mcq BOOLEAN, 
	is_active BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);

-- Table: mcqs
CREATE TABLE mcqs (
	id SERIAL NOT NULL, 
	course_id INTEGER NOT NULL, 
	slide_id INTEGER, 
	type VARCHAR(20) NOT NULL, 
	part VARCHAR(10), 
	question_text TEXT NOT NULL, 
	option_a TEXT NOT NULL, 
	option_b TEXT NOT NULL, 
	option_c TEXT NOT NULL, 
	option_d TEXT NOT NULL, 
	correct_option VARCHAR(5) NOT NULL, 
	explanation TEXT NOT NULL, 
	difficulty VARCHAR(20), 
	marks INTEGER, 
	is_active BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(slide_id) REFERENCES slides (id)
);

-- Table: enrolments
CREATE TABLE enrolments (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	certificate_option VARCHAR(20) NOT NULL, 
	current_slide_number INTEGER, 
	highest_slide_completed INTEGER, 
	slides_completed BOOLEAN, 
	presentation_completions_count INTEGER, 
	attempts_used_in_current_cycle INTEGER, 
	total_time_spent_seconds INTEGER, 
	enrolled_at TIMESTAMP WITHOUT TIME ZONE, 
	completed_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);

-- Table: payment_orders
CREATE TABLE payment_orders (
	id SERIAL NOT NULL, 
	order_reference VARCHAR(64) NOT NULL, 
	enrolment_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	expected_amount FLOAT NOT NULL, 
	currency VARCHAR(10), 
	gst_amount FLOAT, 
	status VARCHAR(50), 
	amount_paid FLOAT, 
	payment_mode VARCHAR(50), 
	payment_date TIMESTAMP WITHOUT TIME ZONE, 
	transaction_reference VARCHAR(100), 
	payer_name VARCHAR(150), 
	payer_account_upi VARCHAR(150), 
	proof_file_path VARCHAR(500), 
	learner_remarks TEXT, 
	customer_gstin VARCHAR(30), 
	customer_org_name VARCHAR(200), 
	customer_billing_address TEXT, 
	customer_state VARCHAR(100), 
	admin_notes TEXT, 
	rejection_reason TEXT, 
	additional_info_notes TEXT, 
	verified_by_user_id INTEGER, 
	verified_at TIMESTAMP WITHOUT TIME ZONE, 
	dual_approved_by_user_id INTEGER, 
	dual_approved_at TIMESTAMP WITHOUT TIME ZONE, 
	submitted_at TIMESTAMP WITHOUT TIME ZONE, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(enrolment_id) REFERENCES enrolments (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(verified_by_user_id) REFERENCES users (id), 
	FOREIGN KEY(dual_approved_by_user_id) REFERENCES users (id)
);

-- Table: certificates
CREATE TABLE certificates (
	id SERIAL NOT NULL, 
	certificate_id VARCHAR(64) NOT NULL, 
	enrolment_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	payment_order_id INTEGER, 
	issue_date DATE NOT NULL, 
	score_percentage FLOAT, 
	course_version VARCHAR(20), 
	status VARCHAR(20), 
	digital_signature_hash VARCHAR(128) NOT NULL, 
	pdf_file_path VARCHAR(500), 
	qr_code_path VARCHAR(500), 
	verification_url VARCHAR(500), 
	dispatch_status VARCHAR(50), 
	courier_name VARCHAR(100), 
	tracking_number VARCHAR(100), 
	dispatched_at TIMESTAMP WITHOUT TIME ZONE, 
	delivered_at TIMESTAMP WITHOUT TIME ZONE, 
	revocation_reason TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(enrolment_id) REFERENCES enrolments (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(payment_order_id) REFERENCES payment_orders (id)
);

-- Table: certificate_complaints
CREATE TABLE certificate_complaints (
	id SERIAL NOT NULL, 
	certificate_id_reported VARCHAR(64), 
	reporter_name VARCHAR(100) NOT NULL, 
	reporter_email VARCHAR(255) NOT NULL, 
	reporter_phone VARCHAR(20), 
	issue_description TEXT NOT NULL, 
	attachment_path VARCHAR(500), 
	consent_given BOOLEAN, 
	status VARCHAR(50), 
	admin_notes TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: test_attempts
CREATE TABLE test_attempts (
	id SERIAL NOT NULL, 
	enrolment_id INTEGER NOT NULL, 
	attempt_number INTEGER NOT NULL, 
	presentation_cycle INTEGER, 
	started_at TIMESTAMP WITHOUT TIME ZONE, 
	submitted_at TIMESTAMP WITHOUT TIME ZONE, 
	score INTEGER, 
	percentage FLOAT, 
	passed BOOLEAN, 
	ip_address VARCHAR(45), 
	user_agent VARCHAR(255), 
	questions_data TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(enrolment_id) REFERENCES enrolments (id)
);

-- Table: slide_view_logs
CREATE TABLE slide_view_logs (
	id SERIAL NOT NULL, 
	enrolment_id INTEGER NOT NULL, 
	slide_id INTEGER NOT NULL, 
	slide_number INTEGER NOT NULL, 
	started_at TIMESTAMP WITHOUT TIME ZONE, 
	completed_at TIMESTAMP WITHOUT TIME ZONE, 
	time_spent_seconds INTEGER, 
	ip_address VARCHAR(45), 
	PRIMARY KEY (id), 
	FOREIGN KEY(enrolment_id) REFERENCES enrolments (id), 
	FOREIGN KEY(slide_id) REFERENCES slides (id)
);

-- Table: practice_mcq_responses
CREATE TABLE practice_mcq_responses (
	id SERIAL NOT NULL, 
	enrolment_id INTEGER NOT NULL, 
	mcq_id INTEGER NOT NULL, 
	selected_option VARCHAR(5) NOT NULL, 
	is_correct BOOLEAN NOT NULL, 
	attempted_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(enrolment_id) REFERENCES enrolments (id), 
	FOREIGN KEY(mcq_id) REFERENCES mcqs (id)
);

-- Table: audit_logs
CREATE TABLE audit_logs (
	id SERIAL NOT NULL, 
	user_id INTEGER, 
	action VARCHAR(100) NOT NULL, 
	entity_type VARCHAR(50), 
	entity_id VARCHAR(100), 
	details TEXT, 
	ip_address VARCHAR(45), 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);

-- Table: email_logs
CREATE TABLE email_logs (
	id SERIAL NOT NULL, 
	recipient VARCHAR(255) NOT NULL, 
	subject VARCHAR(255) NOT NULL, 
	body_html TEXT NOT NULL, 
	status VARCHAR(20), 
	sent_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id)
);

