-- Data for: courses (3 records)
INSERT INTO "courses" ("id", "slug", "title", "short_description", "overview", "estimated_duration", "language", "price_inr", "gst_rate", "price_usd", "version", "is_active", "created_at") VALUES (1, 'good-documentation-practices', 'Good Documentation Practices (GDP)', 'Master essential documentation standards, ALCOA+ principles, data integrity, and regulatory audit compliance across the record life cycle (GxP aligned).', 'This course provides comprehensive training on Good Documentation Practices (GDP) applicable across clinical trials, healthcare data management, and GxP regulated industries. Learners will understand ALCOA+ guidelines, contemporary signature rules, error rectification protocols, and electronic record compliance under 21 CFR Part 11.', '2 Hours', 'English', 499.0, 0.18, 9.49, 'v1.0', TRUE, '2026-11-12T16:32:31.660832');
INSERT INTO "courses" ("id", "slug", "title", "short_description", "overview", "estimated_duration", "language", "price_inr", "gst_rate", "price_usd", "version", "is_active", "created_at") VALUES (2, 'ich-gcp', 'Good Clinical Practices (ICH-GCP)', 'Comprehensive training on ICH E6(R3) guidelines, investigator obligations, Ethics Committees, subject consent, trial monitoring, and quality management.', 'The Good Clinical Practice (GCP) module covers the international ethical, scientific, and quality standards for designing, conducting, recording, and reporting trials involving human subjects. Aligned with the latest International Council for Harmonisation (ICH E6(R2)/(R3)) standards.', '2.5 Hours', 'English', 499.0, 0.18, 9.49, 'v1.0', TRUE, '2026-11-12T16:32:31.672054');
INSERT INTO "courses" ("id", "slug", "title", "short_description", "overview", "estimated_duration", "language", "price_inr", "gst_rate", "price_usd", "version", "is_active", "created_at") VALUES (3, 'new-drugs-clinical-trials-rules-2019', 'New Drugs and Clinical Trial Rules, 2019', 'Master the Indian regulatory landscape under CDSCO, Form CT approvals, Ethics Committee registration, compensation guidelines, and statutory formulas.', 'The New Drugs and Clinical Trial (NDCT) Rules, 2019 comprehensively govern clinical research in India. This module details CDSCO approval pathways (Form CT-04, CT-06), Ethics Committee governance, Academic Clinical Trial exemptions, and statutory compensation for trial-related injuries.', '2 Hours', 'English', 499.0, 0.18, 9.49, 'v1.0', TRUE, '2026-11-12T16:32:31.676303');

