INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (4908, 1, 33, 'Enduring', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  GOOD DOCUMENTATION PRACTICE (GDP)  •  MODULE 02</div>
        <h2 class="slide-title-text">Enduring</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">An enduring record remains:</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Readable.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Secure.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Available for the entire retention period.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Protected against degradation.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Migrated or converted when technology becomes obsolete.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">A temporary electronic file that cannot be opened later is not enduring.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 33</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (4909, 1, 34, 'Available', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  GOOD DOCUMENTATION PRACTICE (GDP)  •  MODULE 02</div>
        <h2 class="slide-title-text">Available</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">Records should be:</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Retrievable within a reasonable time.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Available to authorised reviewers.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Protected from unauthorised access.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Searchable where appropriate.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Available during inspection, audit or investigation.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Availability does not mean unrestricted access.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 34</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (4910, 1, 35, 'ALCOA+ Example', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
