INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (4930, 1, 55, 'MODULE 02 KNOWLEDGE CHECK  |  Question 1: Concept 1: Attributable', '
    <div class="presentation-slide-card slide-type-knowledge_check">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  GOOD DOCUMENTATION PRACTICE (GDP)  •  MODULE 02</div>
        <h2 class="slide-title-text">MODULE 02 KNOWLEDGE CHECK  |  Question 1: Concept 1: Attributable</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-mcq-container">
            <div class="mcq-prompt-card">
                <div class="mcq-badge-pill badge-practice">💡 KNOWLEDGE CHECK ASSESSMENT</div>
                <div class="mcq-question-prompt">Which best demonstrates attribution in an electronic system?</div>
            </div>

            <form class="practice-mcq-form" data-mcq-id="2689">
                <div class="mcq-options-grid">
                    <label class="option-item mcq-option-card" data-opt="A">
                        <input type="radio" name="practice_option" value="A" required>
                        <span class="opt-badge">A</span>
