INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (4942, 1, 67, 'Current Version Control', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
