INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5110, 2, 2, 'ICH GCP Course Curriculum & Module Directory', '
    <div class="presentation-slide-card slide-type-curriculum">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  COURSE CURRICULUM</div>
        <h2 class="slide-title-text">ICH GCP Course Curriculum & Module Directory</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-directory-slide">
            <div class="directory-cards-grid">
                
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 01</div>
                <div class="module-info">
                    <div class="module-card-title">GCP Foundations & R3 Evolution</div>
                    <div class="module-card-desc">Historical evolution, 11 core principles, Quality by Design & proportionality</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 06</div>
                <div class="module-info">
                    <div class="module-card-title">Protocol, IB & Essential Records</div>
                    <div class="module-card-desc">Trial design, Investigator''s Brochure, Trial Master File (TMF) & traceability</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 02</div>
                <div class="module-info">
                    <div class="module-card-title">Ethical Principles & Consent</div>
                    <div class="module-card-desc">Participant rights, safety, vulnerable populations & dynamic informed consent</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 07</div>
                <div class="module-info">
                    <div class="module-card-title">Data Governance & Computerised Systems</div>
                    <div class="module-card-desc">Fit-for-purpose systems, audit trails, data integrity & lifecycle governance</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 03</div>
                <div class="module-info">
                    <div class="module-card-title">IRB / IEC & Independent Review</div>
                    <div class="module-card-desc">Composition, quorum, review procedures, SAE oversight & independence</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 08</div>
                <div class="module-info">
                    <div class="module-card-title">IP Management & Safety Reporting</div>
                    <div class="module-card-desc">Investigational product accountability, blinding, SAE/SUSAR reporting & safety</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 04</div>
                <div class="module-info">
                    <div class="module-card-title">Investigator Responsibilities</div>
                    <div class="module-card-desc">Qualifications, protocol adherence, delegation, medical care & IP control</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 09</div>
                <div class="module-info">
                    <div class="module-card-title">Annex 2: Decentralised & RWD Elements</div>
