INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5123, 2, 15, 'Module 01: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 01</div>
        <h2 class="slide-title-text">Module 01: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 01 - CASE STUDY 1: EXCESSIVE DATA COLLECTION</div>
                    <div class="scenario-body-text">A sponsor collects 420 variables per participant although only 80 are needed for the primary and key secondary objectives. Site staff report that data-entry errors are increasing and participants spend several additional hours completing questionnaires.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Identify the critical-to-quality data.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Determine which variables are unnecessary.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess whether participant burden is justified.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Consider protocol and electronic-case-report-form simplification.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> R3 supports operational feasibility, proportionality and avoidance of unnecessary data collection.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 15</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5124, 2, 16, 'Module 01: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 01</div>
        <h2 class="slide-title-text">Module 01: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 01 - CASE STUDY 2: TECHNOLOGY-ENABLED TRIAL</div>
                    <div class="scenario-body-text">An oncology trial uses a wearable device to measure activity and a mobile application for symptom reporting. The sponsor assumes that the technology is acceptable because it is commercially available.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Commercial availability does not automatically establish fitness for trial purpose.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The device and application require appropriate qualification or validation.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Usability, accessibility, cybersecurity, data transfer and participant training must be assessed.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The protocol should specify how missing or unreliable device data will be handled.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> R3 is technology-neutral but requires fit-for-purpose systems and controlled data processes.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 16</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
