INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5129, 2, 21, 'YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 02', '
    <div class="presentation-slide-card slide-type-module_cover">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 02</div>
        <h2 class="slide-title-text">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 02</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-module-cover">
            <div class="module-separator-tag" style="color: #FFF200 !important; font-weight: 800; font-size: 0.95rem; letter-spacing: 1.2px; text-transform: uppercase; margin-bottom: 12px; text-shadow: 0 1px 3px rgba(0,0,0,0.5);">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 02</div>
            <div class="module-cover-pill" style="background: #FFF200 !important; color: #0A192F !important; font-weight: 900;">MODULE 02</div>
            <h2 class="module-cover-title" style="color: #FFF200 !important; font-size: 1.5rem; font-weight: 800; line-height: 1.3; margin: 8px 0 10px;">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 02</h2>
            <div class="module-cover-desc">Ethical Principles, Participants and Informed Consent
Participant autonomy, vulnerable groups, fair selection, consent comprehension and trial information</div>
