INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5150, 2, 42, 'Purpose of the IRB/IEC', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 03</div>
        <h2 class="slide-title-text">Purpose of the IRB/IEC</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">The IRB/IEC independently reviews the trial to safeguard:</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Rights.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Safety.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Well-being.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Privacy.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Fair treatment.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Interests of vulnerable participants.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">The IRB/IEC is not a substitute for sponsor or investigator responsibility.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 42</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5151, 2, 43, 'Documents Reviewed', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 03</div>
