INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5156, 2, 48, 'IRB/IEC Composition', '
    <div class="presentation-slide-card slide-type-lecture">
        
