INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5159, 2, 51, 'Module 03: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 03</div>
        <h2 class="slide-title-text">Module 03: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">CASE STUDY 1: SCENARIO & CONTEXT</div>
                    <div class="scenario-body-text">A site begins using a social-media advertisement that promises “guaranteed improvement” and offers a payment not included in the approved documents.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Stop use of the material.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Notify the sponsor and IRB/IEC.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess whether participants were misled.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Review whether any participants enrolled because of the advertisement.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Recruitment content is participant-facing trial information and requires appropriate review.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 51</div>
