INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5174, 2, 66, 'Informed Consent at the Site', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
