INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5188, 2, 80, 'Allocation of Activities', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
