INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5197, 2, 89, 'Module 05: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 05</div>
        <h2 class="slide-title-text">Module 05: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 05 - CASE STUDY 1: VENDOR OVERSIGHT FAILURE</div>
                    <div class="scenario-body-text">A central laboratory repeatedly reports delayed and inconsistent results. The sponsor relies on the contract and does not review laboratory performance metrics.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Assess the laboratory as a critical service provider.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Review qualification, validation, performance and deviation history.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Determine impact on participant safety and trial endpoints.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Establish key performance and risk indicators.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Outsourcing an activity does not eliminate sponsor oversight.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 89</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5198, 2, 90, 'Module 05: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 05</div>
        <h2 class="slide-title-text">Module 05: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">CASE STUDY 2: SCENARIO & CONTEXT</div>
                    <div class="scenario-body-text">A monitoring plan requires checking 100% of all data fields but does not include review of consent, eligibility, primary endpoint assessments or investigational-product accountability.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>The plan is resource-intensive but may be poorly risk-focused.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Reassess critical-to-quality factors.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Prioritise participant protection and primary endpoint reliability.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Use central and targeted monitoring where appropriate.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Monitoring intensity should be proportionate and scientifically justified.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 90</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
