INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5216, 2, 108, 'Module 06: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 06</div>
        <h2 class="slide-title-text">Module 06: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 06 - CASE STUDY 1: AMBIGUOUS PRIMARY ENDPOINT</div>
                    <div class="scenario-body-text">A protocol states that progression-free survival will be assessed by “routine imaging” but does not define the imaging method, assessment window or progression criteria.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>The endpoint is not operationally reproducible.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Define imaging modality, timing and assessment rules.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Clarify central versus investigator assessment.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Address missing and delayed scans.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> A clear and feasible protocol is essential for reliable results.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 108</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
