INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5235, 2, 127, 'Module 07: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 07</div>
        <h2 class="slide-title-text">Module 07: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 07 - CASE STUDY 1: DATABASE MIGRATION</div>
                    <div class="scenario-body-text">A sponsor migrates an oncology trial from one EDC system to another. After migration, several date fields are shifted by one day and certain adverse-event coding values are missing.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Quarantine affected data and outputs.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Reconcile source and target datasets.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Review mapping and transformation specifications.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess impact on safety and endpoint analyses.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Data migration is a controlled process requiring documented mapping, reconciliation and verification.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 127</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
