INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5252, 2, 144, 'Immediate Hazards', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 08</div>
        <h2 class="slide-title-text">Immediate Hazards</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">When an immediate hazard occurs:</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Protect the participant first.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Take urgent medical action.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Notify the sponsor.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Notify the IRB/IEC and authorities as required.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Document the event and intervention.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Assess whether treatment or recruitment should be paused.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Implement sustainable corrective action.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
