INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5254, 2, 146, 'Module 08: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 08</div>
        <h2 class="slide-title-text">Module 08: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 08 - CASE STUDY 1: UNEXPECTED SEVERE TOXICITY</div>
                    <div class="scenario-body-text">Several participants develop severe hepatotoxicity within a short period. The sponsor treats the events independently and does not perform aggregate review.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Conduct prompt medical and aggregate review.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess whether a safety signal exists.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Re-evaluate dose, eligibility and monitoring.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Consider treatment interruption.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Safety assessment must consider patterns, not only individual cases.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 146</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
