INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5272, 2, 164, 'Module 09: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 09</div>
        <h2 class="slide-title-text">Module 09: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 09 - CASE STUDY 1: HOME-BASED ONCOLOGY TRIAL</div>
                    <div class="scenario-body-text">Participants receive oral investigational therapy at home, report symptoms through an application and receive home nursing visits. A nurse identifies grade 3 toxicity but cannot contact the investigator after hours.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Define emergency escalation before trial initiation.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Ensure the participant has immediate clinical support.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Define nurse training and reporting timelines.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Maintain source documentation.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Decentralisation requires stronger operational clarity, not less oversight.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 164</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
