INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5290, 2, 182, 'Module 10: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 10</div>
        <h2 class="slide-title-text">Module 10: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 10 - CASE STUDY 1: EARLY TRIAL TERMINATION</div>
                    <div class="scenario-body-text">An interim analysis shows that the investigational treatment is unlikely to meet the primary endpoint. The sponsor stops recruitment but does not inform participants who are still receiving treatment.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Assess participant safety and ongoing treatment.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Inform investigators and participants appropriately.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Follow the protocol’s stopping procedures.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Notify ethics committees and authorities.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Trial termination does not end sponsor and investigator responsibilities.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 182</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5291, 2, 183, 'Module 10: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  ICH GCP TRAINING (ICH E6 R3 ALIGNED)  •  MODULE 10</div>
        <h2 class="slide-title-text">Module 10: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 10 - CASE STUDY 2: SELECTIVE REPORTING</div>
                    <div class="scenario-body-text">A trial report presents favourable secondary endpoints but does not report a failed primary endpoint or important protocol deviations.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>The primary endpoint and relevant deviations must be reported transparently.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Selective reporting can mislead healthcare decision-making.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Reconcile the report with the protocol, SAP and database.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Disclose limitations and deviations objectively.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Reliable evidence requires complete and transparent reporting.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 183</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
