INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5301, 3, 2, 'NDCT Rules 2019 Curriculum & Statutory Module Directory', '
    <div class="presentation-slide-card slide-type-curriculum">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  COURSE CURRICULUM</div>
        <h2 class="slide-title-text">NDCT Rules 2019 Curriculum & Statutory Module Directory</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-directory-slide">
            <div class="directory-cards-grid">
                
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 01</div>
                <div class="module-info">
                    <div class="module-card-title">Background, Evolution & Scope</div>
                    <div class="module-card-desc">Drugs & Cosmetics Act 1940, Schedule Y evolution, GSR 227(E) & statutory architecture</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 06</div>
                <div class="module-info">
                    <div class="module-card-title">Clinical Trials of New Drugs & INDs</div>
                    <div class="module-card-desc">Form CT-04, 30 vs 90-day approvals, deemed approval, CTRI registration & Form CT-06</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 02</div>
                <div class="module-info">
                    <div class="module-card-title">Definitions & Regulatory Classification</div>
                    <div class="module-card-desc">New drugs, IND, orphan drugs, modified formulations, academic trials & SAEs</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 07</div>
                <div class="module-info">
                    <div class="module-card-title">Bioavailability & Bioequivalence Studies</div>
                    <div class="module-card-desc">Centre registration (CT-09), study permission (CT-06/CT-05), PK metrics & sample custody</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 03</div>
                <div class="module-info">
                    <div class="module-card-title">Authorities & Regulatory Architecture</div>
                    <div class="module-card-desc">CDSCO, CLA, State Licensing Authorities, Subject Expert Committees (SEC) & inspection powers</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 08</div>
                <div class="module-info">
                    <div class="module-card-title">Manufacture for Research & Analysis</div>
                    <div class="module-card-desc">Form CT-10, test licence (CT-11), API sourcing, GMP standards & product packaging CT-20</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 04</div>
                <div class="module-info">
                    <div class="module-card-title">Ethics Committees (CT & BA/BE)</div>
                    <div class="module-card-desc">Mandatory registration, composition, 50% non-affiliated quorum, decision making & renewal</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 09</div>
                <div class="module-info">
                    <div class="module-card-title">Import, Approval & Special Pathways</div>
                    <div class="module-card-desc">Form CT-18/19, fast-track review, local clinical trial waiver & post-trial access</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 05</div>
                <div class="module-info">
                    <div class="module-card-title">Biomedical & Health Research</div>
                    <div class="module-card-desc">DHR registration, ICMR National Ethical Guidelines 2017, distinction from clinical trials</div>
                </div>
            </div>
            
            <div class="directory-module-card">
                <div class="module-badge-pill">Module 10</div>
                <div class="module-info">
