INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5304, 3, 5, 'The Drugs and Cosmetics Act, 1940', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 01</div>
        <h2 class="slide-title-text">The Drugs and Cosmetics Act, 1940</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">The Drugs and Cosmetics Act, 1940 is the principal central legislation governing:</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Import of drugs.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Manufacture of drugs.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Distribution and sale.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Standards of quality.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Regulatory powers and enforcement.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Rule-making authority for drugs and cosmetics.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">The Act creates the legal foundation; detailed operational requirements are provided through Rules and schedules.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 5</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5305, 3, 6, 'The Drugs and Cosmetics Rules, 1945', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 01</div>
        <h2 class="slide-title-text">The Drugs and Cosmetics Rules, 1945</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">The Drugs and Cosmetics Rules, 1945 provided detailed procedures under the Act, including requirements for:</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Licences.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Manufacturing.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Import.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Testing.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Labelling.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">New drugs.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Clinical trials.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Regulatory submissions.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Before NDCT 2019, many clinical-trial and new-drug provisions were located in Schedule Y and Part XA.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 6</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5306, 3, 7, 'Schedule Y: Earlier Framework', '
