INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5346, 3, 47, 'Delegation of Powers', '
    <div class="presentation-slide-card slide-type-lecture">
        
