INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5353, 3, 54, 'Module 03: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 03</div>
        <h2 class="slide-title-text">Module 03: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">CASE STUDY 1: SCENARIO & CONTEXT</div>
                    <div class="scenario-body-text">A manufacturer obtains a state manufacturing licence for a modified-release product but has not obtained prior new-drug permission from CDSCO.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>A state licence does not replace required central permission.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Determine whether the product qualifies as a new drug.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Review the correct application and manufacturing pathway.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Avoid commercial manufacture until all required permissions are in place.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Central and state approvals may be sequential and complementary.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 54</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
