INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5372, 3, 73, 'Module 04: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 04</div>
        <h2 class="slide-title-text">Module 04: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 04 - CASE STUDY 1: INADEQUATE QUORUM</div>
                    <div class="scenario-body-text">An Ethics Committee reviews a high-risk first-in-human trial with only four members present and no lay person.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>The required quorum is not met.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The review should not proceed as a valid protocol decision.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The meeting should be rescheduled.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Minutes should clearly record attendance and quorum.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Ethical review is valid only when the required composition and quorum are met.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 73</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5373, 3, 74, 'Module 04: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 04</div>
        <h2 class="slide-title-text">Module 04: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 04 - CASE STUDY 2: UNDECLARED CONFLICT</div>
                    <div class="scenario-body-text">The Ethics Committee Chairperson owns shares in the sponsor company and chairs the review without declaring the interest.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>The conflict threatens independence.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The member should not participate in the review.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The conflict must be recorded.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The institution should follow its conflict-management process.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Conflicts can affect both ethical independence and regulatory credibility.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 74</div>
