INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5386, 3, 87, 'Distinguishing Research Categories in India', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 05</div>
        <h2 class="slide-title-text">Distinguishing Research Categories in India</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            <div class="lecture-lead-text">CLINICAL TRIALS & BA/BE (CDSCO / CLA)</div>
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">BIOMEDICAL & HEALTH RESEARCH (ICMR / DHR)</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Regulated under Chapters V, VI & VII of NDCT Rules 2019.</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Involves new drugs, investigational products or human bioavailability comparison.</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Requires statutory permission from Central Licensing Authority (Form CT-06 / CT-20).</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Mandatory registration of Ethics Committee with CDSCO; strict statutory SAE compensation rules.</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Regulated under Chapter IV of NDCT Rules 2019 and ICMR Guidelines (2017).</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Involves basic, socio-behavioral, observational, or diagnostic human research without new drugs.</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">No CLA permission required; reviewed and approved by DHR-registered Institutional Ethics Committee.</span>
        </li>
        
        <li class="lecture-list-item icon-bullet">
            <span class="item-symbol">•</span>
            <span class="item-content">Follows ICMR National Ethical Guidelines for oversight, consent, and participant protection.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 87</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
