INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5390, 3, 91, 'Module 05: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 05</div>
        <h2 class="slide-title-text">Module 05: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">CASE STUDY 1: SCENARIO & CONTEXT</div>
                    <div class="scenario-body-text">A hospital proposes to use stored blood samples for genetic research, but the original consent permitted only the parent clinical trial.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Review the original consent and Ethics Committee approval.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess whether secondary use is covered.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Consider re-consent or waiver procedures where permitted.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Address genetic privacy and group harms.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Secondary use of biological material requires ethical and consent analysis.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 91</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5391, 3, 92, 'Module 05: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 05</div>
        <h2 class="slide-title-text">Module 05: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">CASE STUDY 2: SCENARIO & CONTEXT</div>
                    <div class="scenario-body-text">A research group labels a study “observational,” but investigators assign participants to different treatment regimens.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Allocation of treatment indicates an interventional design.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The study may fall within clinical-trial requirements.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The protocol, approval pathway and regulatory submissions must be reassessed.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>The team should not rely on the study title to avoid regulation.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Regulatory classification depends on actual conduct, not the label used by the investigator.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 92</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5392, 3, 93, 'MODULE 05 KNOWLEDGE CHECK  |  Question 1', '
    <div class="presentation-slide-card slide-type-knowledge_check">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 05</div>
        <h2 class="slide-title-text">MODULE 05 KNOWLEDGE CHECK  |  Question 1</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-mcq-container">
            <div class="mcq-prompt-card">
                <div class="mcq-badge-pill badge-practice">💡 KNOWLEDGE CHECK ASSESSMENT</div>
                <div class="mcq-question-prompt">Biomedical and health research is primarily governed ethically through:</div>
            </div>

            <form class="practice-mcq-form" data-mcq-id="2939">
                <div class="mcq-options-grid">
                    <label class="option-item mcq-option-card" data-opt="A">
                        <input type="radio" name="practice_option" value="A" required>
                        <span class="opt-badge">A</span>
                        <span class="opt-text">ICMR National Ethical Guidelines and Chapter IV</span>
                    </label>
                    <label class="option-item mcq-option-card" data-opt="B">
                        <input type="radio" name="practice_option" value="B" required>
                        <span class="opt-badge">B</span>
                        <span class="opt-text">Marketing regulations only</span>
                    </label>
                    <label class="option-item mcq-option-card" data-opt="C">
                        <input type="radio" name="practice_option" value="C" required>
                        <span class="opt-badge">C</span>
                        <span class="opt-text">Product-labelling rules only</span>
                    </label>
                    <label class="option-item mcq-option-card" data-opt="D">
                        <input type="radio" name="practice_option" value="D" required>
                        <span class="opt-badge">D</span>
                        <span class="opt-text">Tax legislation</span>
                    </label>
                </div>

                <!-- Dual response input: Click option card above OR type letter A, B, C, D below -->
                <div class="mcq-dual-response-bar">
                    <div class="dual-input-wrap">
                        <span class="dual-label">Selected Response:</span>
