INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5413, 3, 114, 'MODULE 06 KNOWLEDGE CHECK  |  Question 2', '
    <div class="presentation-slide-card slide-type-knowledge_check">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 06</div>
        <h2 class="slide-title-text">MODULE 06 KNOWLEDGE CHECK  |  Question 2</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
