INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5429, 3, 130, 'Module 07: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 07</div>
        <h2 class="slide-title-text">Module 07: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 07 - CASE STUDY 1: SAMPLING-TIME ERROR</div>
                    <div class="scenario-body-text">In a BE study, several blood samples are collected 20 minutes outside the scheduled window, but the site records the protocol time instead of the actual time.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>This compromises data integrity and pharmacokinetic interpretation.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Actual collection time must be retained.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess affected profiles and protocol deviation impact.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Notify the sponsor and Ethics Committee/regulator as required.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Accurate timing is critical to BA/BE validity.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 130</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5430, 3, 131, 'Module 07: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 07</div>
        <h2 class="slide-title-text">Module 07: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 07 - CASE STUDY 2: UNREGISTERED BA/BE CENTRE</div>
                    <div class="scenario-body-text">A sponsor begins a human BA/BE study at a hospital whose clinical facility is suitable but whose BA/BE centre registration has not been obtained.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>The study should not begin until required registration is confirmed.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Obtain regulatory clarification and assess any activities already performed.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Confirm Ethics Committee approval and facility responsibilities.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Implement a centre-qualification checklist.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Clinical capability alone does not establish regulatory registration.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 131</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
