INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5446, 3, 147, 'Current Test-Manufacture Reform', '
    <div class="presentation-slide-card slide-type-lecture">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 08</div>
        <h2 class="slide-title-text">Current Test-Manufacture Reform</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-lecture-slide">
            
            <ul class="lecture-items-list">
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">The 2026 amendments replace the requirement for a test licence with prior online intimation for specified non-commercial manufacture categories.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Exceptions include specified high-risk products such as:</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Cytotoxic drugs.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Narcotic drugs.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Psychotropic substances.</span>
        </li>
        
        <li class="lecture-list-item icon-arrow">
            <span class="item-symbol">▸</span>
            <span class="item-content">Where a licence remains required, the statutory processing period has been reduced from 90 to 45 days according to the Ministry announcement.</span>
        </li>
        </ul>
            
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 147</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5447, 3, 148, 'Module 08: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 08</div>
        <h2 class="slide-title-text">Module 08: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 08 - CASE STUDY 1: CYTOTOXIC TEST BATCH</div>
                    <div class="scenario-body-text">A company assumes that a small non-commercial batch of a cytotoxic oncology drug qualifies for prior intimation and begins manufacture without a test licence.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Cytotoxic products are identified as an exception in the Ministry announcement.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Confirm the current Gazette wording and category.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Obtain the required permission before manufacture.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Review any material already produced.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Simplified pathways may exclude high-risk products.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 148</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5448, 3, 149, 'Module 08: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 08</div>
