INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5466, 3, 167, 'Module 09: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 09</div>
        <h2 class="slide-title-text">Module 09: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 09 - CASE STUDY 1: RARE PAEDIATRIC DISEASE</div>
                    <div class="scenario-body-text">A sponsor proposes a gene therapy for a rare paediatric disease with no approved treatment. The available patient population is very small.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Consider orphan-drug and unmet-need provisions.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Build a scientifically justified development plan.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Address long-term safety follow-up.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Include paediatric consent and assent.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Regulatory flexibility may support development but does not reduce the need for evidence and long-term monitoring.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 167</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5467, 3, 168, 'Module 09: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 09</div>
        <h2 class="slide-title-text">Module 09: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 09 - CASE STUDY 2: POST-TRIAL ACCESS</div>
                    <div class="scenario-body-text">An investigational oncology drug produced meaningful benefit in one participant, and no alternative therapy is available after trial completion.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Investigator should assess continued benefit and risks.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Ethics Committee approval is required.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Written participant consent is needed.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Sponsor responsibilities and duration should be documented.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Post-trial access is a structured ethical and regulatory process, not an informal continuation of treatment.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 168</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
