INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5477, 3, 178, 'SAE Assessment', '
    <div class="presentation-slide-card slide-type-lecture">
        
