INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5485, 3, 186, 'Module 10: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 10</div>
        <h2 class="slide-title-text">Module 10: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 10 - CASE STUDY 1: DELAYED SAE REPORTING</div>
                    <div class="scenario-body-text">A site reports a hospitalisation-related SAE 20 days after becoming aware of it because the investigator was on leave.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Determine the applicable reporting timeline.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Submit the delayed report promptly.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Assess whether the delay affected participant safety.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Identify delegation and backup failures.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Operational delegation and backup arrangements are essential for time-critical safety reporting.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 186</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5486, 3, 187, 'Module 10: Real-World Case Study', '
    <div class="presentation-slide-card slide-type-case_study">
        
    <div class="slide-presentation-header">
        <div class="slide-accent-bar"></div>
        <div class="slide-breadcrumb">YTAL TECH E-LEARNING  |  NEW DRUGS & CLINICAL TRIALS RULES, 2019  •  MODULE 10</div>
        <h2 class="slide-title-text">Module 10: Real-World Case Study</h2>
        <div class="slide-title-underline"></div>
    </div>
    
        <div class="slide-content-area">
            
        <div class="presentation-case-study">
            <div class="case-study-top-grid">
                <div class="case-study-scenario-card">
                    <div class="scenario-badge">MODULE 10 - CASE STUDY 2: COMPENSATION DISPUTE</div>
                    <div class="scenario-body-text">A participant develops a serious injury during a trial. The sponsor argues that the disease, rather than the investigational product, caused the event and refuses medical support while causality is being assessed.</div>
                </div>
                <div class="case-study-discussion-card">
                    <div class="discussion-heading">REGULATORY ASSESSMENT & DISCUSSION</div>
                    <ul class="discussion-list">
                        <li class="discussion-item"><span class="disc-marker">▸</span><span>Medical management should not be delayed.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Causality assessment and compensation determination are separate processes.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Preserve clinical records and obtain expert assessment.</span></li><li class="discussion-item"><span class="disc-marker">▸</span><span>Notify the Ethics Committee and regulator as required.</span></li>
                    </ul>
                </div>
            </div>
            <div class="case-study-takeaway-card"><strong>KEY REGULATORY TAKEAWAY:</strong> Patient care and regulatory assessment must proceed in parallel.</div>
        </div>
        
        </div>
        
    <div class="slide-presentation-footer">
        <div class="footer-left">Ytal Tech E-Learning Platform • <a href="https://www.ytaltech.com" target="_blank">www.ytaltech.com</a></div>
        <div class="footer-right">Page 187</div>
    </div>
    
    </div>
    ', NULL, 15, FALSE, TRUE);
INSERT INTO "slides" ("id", "course_id", "slide_number", "title", "content_html", "image_url", "minimum_dwell_seconds", "has_practice_mcq", "is_active") VALUES (5487, 3, 188, 'MODULE 10 KNOWLEDGE CHECK  |  Question 1', '
