INSERT INTO "test_attempts" ("id", "enrolment_id", "attempt_number", "presentation_cycle", "started_at", "submitted_at", "score", "percentage", "passed", "ip_address", "user_agent", "questions_data") VALUES (3, 1, 1, 1, '2026-11-27T02:34:04.349055', '2026-11-27T02:34:04.390592', 18, 90.0, TRUE, '127.0.0.1', '', '[{"id": 2781, "number": 1, "question_text": "A document reviewer should confirm:", "user_choice": "B", "user_choice_text": "The document is scientifically and operationally suitable", "is_correct": true, "correct_option": "B", "correct_option_text": "The document is scientifically and operationally suitable", "explanation": "This standard directly reinforces Good Documentation Practice: The document is scientifically and operationally suitable."}, {"id": 2729, "number": 2, "question_text": "Data integrity requires data to be:", "user_choice": "C", "user_choice_text": "Complete, consistent and accurate throughout the life cycle", "is_correct": true, "correct_option": "C", "correct_option_text": "Complete, consistent and accurate throughout the life cycle", "explanation": "According to Good Documentation Practice and ALCOA+ principles, data integrity requires data to be: is governed by Option C."}, {"id": 2790, "number": 3, "question_text": "A data-integrity investigation should first ensure that:", "user_choice": "B", "user_choice_text": "Relevant records and evidence are preserved", "is_correct": true, "correct_option": "B", "correct_option_text": "Relevant records and evidence are preserved", "explanation": "This standard directly reinforces Good Documentation Practice: Relevant records and evidence are preserved."}, {"id": 2769, "number": 4, "question_text": "Which is the most serious concern with pre-signing a record?", "user_choice": "C", "user_choice_text": "It may misrepresent when the activity occurred", "is_correct": true, "correct_option": "C", "correct_option_text": "It may misrepresent when the activity occurred", "explanation": "This standard directly reinforces Good Documentation Practice: It may misrepresent when the activity occurred."}, {"id": 2775, "number": 5, "question_text": "An uncontrolled spreadsheet used for GMP release calculations creates a risk because:", "user_choice": "B", "user_choice_text": "Its formulas and changes may not be controlled or validated", "is_correct": true, "correct_option": "B", "correct_option_text": "Its formulas and changes may not be controlled or validated", "explanation": "This standard directly reinforces Good Documentation Practice: Its formulas and changes may not be controlled or validated."}, {"id": 2782, "number": 6, "question_text": "Which is an example of complete data?", "user_choice": "C", "user_choice_text": "All results, including failures and repeats, are retained", "is_correct": true, "correct_option": "C", "correct_option_text": "All results, including failures and repeats, are retained", "explanation": "This standard directly reinforces Good Documentation Practice: All results, including failures and repeats, are retained."}, {"id": 2774, "number": 7, "question_text": "A document\u2019s effective date indicates:", "user_choice": "D", "user_choice_text": "When the approved version becomes applicable", "is_correct": true, "correct_option": "D", "correct_option_text": "When the approved version becomes applicable", "explanation": "This standard directly reinforces Good Documentation Practice: When the approved version becomes applicable."}, {"id": 2783, "number": 8, "question_text": "A record may be accurate but not complete when:", "user_choice": "D", "user_choice_text": "A relevant failed test is omitted", "is_correct": true, "correct_option": "D", "correct_option_text": "A relevant failed test is omitted", "explanation": "This standard directly reinforces Good Documentation Practice: A relevant failed test is omitted."}, {"id": 2767, "number": 9, "question_text": "During an inspection, personnel should:", "user_choice": "B", "user_choice_text": "Answer honestly and avoid speculation", "is_correct": true, "correct_option": "B", "correct_option_text": "Answer honestly and avoid speculation", "explanation": "According to Good Documentation Practice and ALCOA+ principles, during an inspection, personnel should: is governed by Option B."}, {"id": 2776, "number": 10, "question_text": "Which activity should be documented in a deviation record?", "user_choice": "D", "user_choice_text": "A process occurring outside the approved procedure", "is_correct": true, "correct_option": "D", "correct_option_text": "A process occurring outside the approved procedure", "explanation": "This standard directly reinforces Good Documentation Practice: A process occurring outside the approved procedure."}, {"id": 2787, "number": 11, "question_text": "A record archive should be:", "user_choice": "D", "user_choice_text": "Indexed and retrievable", "is_correct": true, "correct_option": "D", "correct_option_text": "Indexed and retrievable", "explanation": "This standard directly reinforces Good Documentation Practice: Indexed and retrievable."}, {"id": 2751, "number": 12, "question_text": "A document revision should include:", "user_choice": "D", "user_choice_text": "A description and rationale for the change", "is_correct": true, "correct_option": "D", "correct_option_text": "A description and rationale for the change", "explanation": "According to Good Documentation Practice and ALCOA+ principles, a document revision should include: is governed by Option D."}, {"id": 2727, "number": 13, "question_text": "Updated prompt for test #2727 - ALCOA+ compliance check", "user_choice": "C", "user_choice_text": "Option C Modified", "is_correct": true, "correct_option": "C", "correct_option_text": "Option C Modified", "explanation": "Updated explanation for regulatory standard."}, {"id": 2744, "number": 14, "question_text": "Why are shared user accounts unacceptable in regulated systems?", "user_choice": "D", "user_choice_text": "They prevent reliable identification of the person performing an action", "is_correct": true, "correct_option": "D", "correct_option_text": "They prevent reliable identification of the person performing an action", "explanation": "According to Good Documentation Practice and ALCOA+ principles, why are shared user accounts unacceptable in regulated systems is governed by Option D."}, {"id": 2777, "number": 15, "question_text": "The \u201coriginal\u201d in an electronic system may include:", "user_choice": "A", "user_choice_text": "Original data plus relevant metadata and audit trail", "is_correct": true, "correct_option": "A", "correct_option_text": "Original data plus relevant metadata and audit trail", "explanation": "This standard directly reinforces Good Documentation Practice: Original data plus relevant metadata and audit trail."}, {"id": 2755, "number": 16, "question_text": "The purpose of independent review is to:", "user_choice": "D", "user_choice_text": "Detect errors and confirm compliance", "is_correct": true, "correct_option": "D", "correct_option_text": "Detect errors and confirm compliance", "explanation": "According to Good Documentation Practice and ALCOA+ principles, the purpose of independent review is to: is governed by Option D."}, {"id": 2765, "number": 17, "question_text": "GLP raw data should include:", "user_choice": "B", "user_choice_text": "Original observations and supporting context", "is_correct": true, "correct_option": "B", "correct_option_text": "Original observations and supporting context", "explanation": "According to Good Documentation Practice and ALCOA+ principles, glp raw data should include: is governed by Option B."}, {"id": 2768, "number": 18, "question_text": "Which attribute means that a record identifies the person or system responsible for creating it?", "user_choice": "A", "user_choice_text": "Attributable", "is_correct": true, "correct_option": "A", "correct_option_text": "Attributable", "explanation": "This standard directly reinforces Good Documentation Practice: Attributable."}, {"id": 2757, "number": 19, "question_text": "A missed entry should be:", "user_choice": "B", "user_choice_text": "Invented from memory", "is_correct": false, "correct_option": "A", "correct_option_text": "Made as a traceable late entry with explanation", "explanation": "According to Good Documentation Practice and ALCOA+ principles, a missed entry should be: is governed by Option A."}, {"id": 2736, "number": 20, "question_text": "Consistency requires:", "user_choice": "A", "user_choice_text": "Every record to have the same handwriting", "is_correct": false, "correct_option": "C", "correct_option_text": "Related records to follow a logical chronology and use compatible information", "explanation": "According to Good Documentation Practice and ALCOA+ principles, consistency requires: is governed by Option C."}]');

